    end
  end

  on_linux do
    on_intel do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.15/whycodes-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "3dce398bf102759b6de3af113af0311ac4474eb891944241c0a0f966b6276028"
    end
  end

  head do
